            "Erstelle ein Aufgabenboard und teile ID, Passwort und URL. Mache den Teamfortschritt ohne Registrierung in Echtzeit sichtbar.",
            "Erstelle ein Aufgabenboard oder tritt einem bei – ohne Konto. Organisiere offene, laufende und erledigte Aufgaben gemeinsam.",
            "Geteiltes Aufgabenboard",
