            "Erstelle und teile ein Aufgabenboard, damit mehrere Personen offene, laufende und erledigte Aufgaben gemeinsam organisieren können. Ideal für Veranstaltungsplanung, Meeting-TODOs, Teamentwicklung und Arbeiten, die sofort beginnen sollen.",
