            "साझा टास्क बोर्ड",
            "टीम के कार्यों को रीयल टाइम कानबन में प्रबंधित करें",
            "एक टास्क बोर्ड बनाएँ और साझा करें ताकि कई लोग एक ही बोर्ड पर करने योग्य, प्रगति पर और पूर्ण कार्यों को व्यवस्थित कर सकें। यह कार्यक्रम की तैयारी, मीटिंग TODO, टीम विकास और तुरंत शुरू किए जाने वाले कामों के लिए उपयोगी है।",
