            "নিবন্ধন ছাড়া শেয়ার করা টাস্ক বোর্ড | FS!QR Task",
            "FS!QR Task হলো নিবন্ধন ছাড়াই ব্যবহারযোগ্য একটি শেয়ার করা টাস্ক বোর্ড। একটি রুম তৈরি করে তার ID, পাসওয়ার্ড ও URL শেয়ার করুন এবং অন্যদের সঙ্গে করণীয়, চলমান ও সম্পন্ন টাস্ক রিয়েল টাইমে পরিচালনা করুন।",
            "টাস্ক রুমে প্রবেশ, শেয়ার করা টাস্ক বোর্ড, কানবান ব্যবস্থাপনা, টাস্কে যোগদান, TODO ব্যবস্থাপনা, সহযোগিতার টুল, FS QR Task",
