def main() -> None:
    if len(TRANSLATIONS["en"]) != len(SOURCE_STRINGS):
        raise SystemExit(
            f"English translation count mismatch: {len(TRANSLATIONS['en'])} != {len(SOURCE_STRINGS)}"
        )
    if len(TRANSLATIONS["ja"]) != len(SOURCE_STRINGS):
        raise SystemExit("Japanese source count mismatch")
    if set(UI_TRANSLATIONS) != set(TRANSLATIONS):
        raise SystemExit("UI translation language set mismatch")
    if set(JS_TRANSLATIONS) != set(TRANSLATIONS):
        raise SystemExit("JS translation language set mismatch")
    for language, values in UI_TRANSLATIONS.items():
        if len(values) != len(UI_KEYS):
            raise SystemExit(
                f"UI translation count mismatch for {language}: "
                f"{len(values)} != {len(UI_KEYS)}"
            )
    for language, values in JS_TRANSLATIONS.items():
        if len(values) != len(JS_KEYS):
            raise SystemExit(
                f"JS translation count mismatch for {language}: "
                f"{len(values)} != {len(JS_KEYS)}"
            )

    for language, values in TRANSLATIONS.items():
        path = LOCALES_DIR / language / "phrases" / "task.json"
        path.write_text(
            json.dumps(dict(zip(SOURCE_STRINGS, values)), ensure_ascii=False, indent=2)
            + "\n",
            encoding="utf-8",
        )
        ui_path = LOCALES_DIR / language / "ui.json"
        ui_values = json.loads(ui_path.read_text(encoding="utf-8"))
        ui_values.update(dict(zip(UI_KEYS, UI_TRANSLATIONS[language])))
        ui_path.write_text(
            json.dumps(ui_values, ensure_ascii=False, indent=2) + "\n",
            encoding="utf-8",
        )
        js_path = LOCALES_DIR / language / "js.json"
        js_values = json.loads(js_path.read_text(encoding="utf-8"))
        js_values.update(dict(zip(JS_KEYS, JS_TRANSLATIONS[language])))
        js_path.write_text(
            json.dumps(js_values, ensure_ascii=False, indent=2) + "\n",
            encoding="utf-8",
        )


if __name__ == "__main__":
    main()
